mapper.select:
SELECT FROM tb_permission p
ORDER BY ${sortColumn} ${sortDirection}, p.perm_id ASC
LIMIT #{size} OFFSET #{offset}

SELECT 
  FROM tb_permission p
 WHERE p.perm_id = #{permId}

mapper.insert:
INSERT INTO tb_permission (
    perm_id, perm_name, module_code, menu_path, sort_order, use_yn, created_by
) VALUES (
    #{permId}, #{permName}, #{moduleCode}, #{menuPath}, #{sortOrder}, #{useYn}, #{createdBy}
)

mapper.select:
SELECT r.role_name || '(' || string_agg(rp.action_code, ',' ORDER BY rp.action_code) || ')' FROM tb_role_permission rp JOIN tb_role r ON r.role_seq = rp.role_seq WHERE rp.perm_seq = #{permSeq}
AND rp.action_code NOT IN
#{action}
GROUP BY r.role_name ORDER BY r.role_name
